package com.acme.relay.config;

import java.io.IOException;
import java.io.Reader;
import java.net.URI;
import java.net.URISyntaxException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Properties;
import java.util.Set;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Reads the relay's configuration from a properties file.
 *
 * <p>Any value that is missing, malformed or out of range, and any key the relay does not know, makes loading fail
 * with a {@link ConfigException} that lists every problem. Only keys that are absent fall back to their defaults.
 */
public final class ConfigLoader {
    static final int DEFAULT_WORKER_THREADS = 4;
    static final int DEFAULT_QUEUE_CAPACITY = 1000;
    static final int DEFAULT_RETRY_ATTEMPTS = 3;
    static final Duration DEFAULT_REQUEST_TIMEOUT = Duration.ofSeconds(30);

    private static final String UPSTREAM_URL = "upstream.url";
    private static final String API_TOKEN = "api.token";
    private static final String WORKER_THREADS = "worker.threads";
    private static final String QUEUE_CAPACITY = "queue.capacity";
    private static final String RETRY_ATTEMPTS = "retry.max-attempts";
    private static final String REQUEST_TIMEOUT = "request.timeout";
    private static final String METRICS_ENABLED = "metrics.enabled";
    private static final Set<String> KNOWN_KEYS = Set.of(
            UPSTREAM_URL, API_TOKEN, WORKER_THREADS, QUEUE_CAPACITY, RETRY_ATTEMPTS, REQUEST_TIMEOUT, METRICS_ENABLED);

    private static final Pattern DURATION = Pattern.compile("(\\d+)(ms|s|m)");

    private final Properties properties;
    private final List<String> problems = new ArrayList<>();

    private ConfigLoader(Properties properties) {
        this.properties = properties;
    }

    public static ServiceConfig load(Path file) {
        return new ConfigLoader(read(file)).parse(file);
    }

    private ServiceConfig parse(Path file) {
        rejectUnknownKeys();
        ServiceConfig config = new ServiceConfig(
                uri(UPSTREAM_URL),
                required(API_TOKEN),
                intValue(WORKER_THREADS, DEFAULT_WORKER_THREADS, 1),
                intValue(QUEUE_CAPACITY, DEFAULT_QUEUE_CAPACITY, 1),
                intValue(RETRY_ATTEMPTS, DEFAULT_RETRY_ATTEMPTS, 0),
                duration(REQUEST_TIMEOUT, DEFAULT_REQUEST_TIMEOUT),
                bool(METRICS_ENABLED, false));
        if (!problems.isEmpty()) {
            throw new ConfigException(
                    "Invalid configuration in " + file + ":" + System.lineSeparator() + "  - "
                            + String.join(System.lineSeparator() + "  - ", problems));
        }
        return config;
    }

    private static Properties read(Path file) {
        Properties properties = new Properties();
        try (Reader reader = Files.newBufferedReader(file)) {
            properties.load(reader);
        } catch (IOException | IllegalArgumentException e) {
            throw new ConfigException("Cannot read configuration file " + file.toAbsolutePath() + ": " + e);
        }
        return properties;
    }

    private void rejectUnknownKeys() {
        for (String key : new TreeSet<>(properties.stringPropertyNames())) {
            if (!KNOWN_KEYS.contains(key)) {
                problems.add(key + ": unknown key (known keys: " + new TreeSet<>(KNOWN_KEYS) + ")");
            }
        }
    }

    /** The trimmed value, or null when the key is absent. */
    private String raw(String key) {
        String value = properties.getProperty(key);
        return value == null ? null : value.trim();
    }

    private String invalid(String key, String raw, String expected) {
        problems.add(key + ": '" + raw + "' is not valid, expected " + expected);
        return null;
    }

    private String required(String key) {
        String value = raw(key);
        if (value == null || value.isEmpty()) {
            problems.add(key + ": is required");
            return null;
        }
        return value;
    }

    private URI uri(String key) {
        String value = required(key);
        if (value == null) {
            return null;
        }
        try {
            URI uri = new URI(value);
            if (uri.isAbsolute() && uri.getHost() != null) {
                return uri;
            }
        } catch (URISyntaxException e) {
            // reported below
        }
        invalid(key, value, "an absolute URL such as https://host/path");
        return null;
    }

    private int intValue(String key, int defaultValue, int minimum) {
        String value = raw(key);
        if (value == null) {
            return defaultValue;
        }
        String expected = "a whole number, at least " + minimum;
        try {
            int parsed = Integer.parseInt(value);
            if (parsed >= minimum) {
                return parsed;
            }
        } catch (NumberFormatException e) {
            // reported below
        }
        invalid(key, value, expected);
        return defaultValue;
    }

    private Duration duration(String key, Duration defaultValue) {
        String value = raw(key);
        if (value == null) {
            return defaultValue;
        }
        Matcher matcher = DURATION.matcher(value);
        try {
            if (matcher.matches()) {
                Duration parsed = toDuration(Long.parseLong(matcher.group(1)), matcher.group(2));
                if (!parsed.isZero()) {
                    return parsed;
                }
            }
        } catch (ArithmeticException | NumberFormatException e) {
            // reported below
        }
        invalid(key, value, "a positive whole number followed by ms, s or m, such as 30s");
        return defaultValue;
    }

    private static Duration toDuration(long amount, String unit) {
        return switch (unit) {
            case "ms" -> Duration.ofMillis(amount);
            case "s" -> Duration.ofSeconds(amount);
            default -> Duration.ofMinutes(amount);
        };
    }

    private boolean bool(String key, boolean defaultValue) {
        String value = raw(key);
        if (value == null) {
            return defaultValue;
        }
        if (value.equalsIgnoreCase("true") || value.equalsIgnoreCase("false")) {
            return Boolean.parseBoolean(value);
        }
        invalid(key, value, "true or false");
        return defaultValue;
    }
}

